+import { expect, test } from "bun:test";
+import { nextRun } from "./cron";
+
+const at = (iso: string) => new Date(iso);
+
+test("weekday names, in any case", () => {
+  expect(nextRun("0 9 * * MON-FRI", at("2026-01-02T09:00:00Z")).toISOString()).toBe("2026-01-05T09:00:00.000Z");
+  expect(nextRun("0 9 * jan mon", at("2026-01-05T09:00:00Z")).toISOString()).toBe("2026-01-12T09:00:00.000Z");
+});
+
+test("month names with a step", () => {
+  expect(nextRun("0 0 1 JAN-MAR/2 *", at("2026-01-02T00:00:00Z")).toISOString()).toBe("2026-03-01T00:00:00.000Z");
+});
+
+test("a step on a lone value runs to the end of the field", () => {
+  expect(nextRun("5/20 * * * *", at("2026-01-01T00:00:00Z")).toISOString()).toBe("2026-01-01T00:05:00.000Z");
+  expect(nextRun("5/20 * * * *", at("2026-01-01T00:05:00Z")).toISOString()).toBe("2026-01-01T00:25:00.000Z");
+});
+
+test("steps over a star and a range", () => {
+  expect(nextRun("*/15 * * * *", at("2026-01-01T00:00:00Z")).toISOString()).toBe("2026-01-01T00:15:00.000Z");
+  expect(nextRun("10-30/10 * * * *", at("2026-01-01T00:10:00Z")).toISOString()).toBe("2026-01-01T00:20:00.000Z");
+  expect(nextRun("10-30/10 * * * *", at("2026-01-01T00:30:00Z")).toISOString()).toBe("2026-01-01T01:10:00.000Z");
+});
+
+test("Sunday written as 7", () => {
+  expect(nextRun("0 12 * * 7", at("2026-01-01T00:00:00Z")).toISOString()).toBe("2026-01-04T12:00:00.000Z");
+  expect(nextRun("0 12 * * 0-7", at("2025-12-31T12:00:00Z")).toISOString()).toBe("2026-01-01T12:00:00.000Z");
+});
+
+test("both a day of month and a day of week", () => {
+  expect(nextRun("0 0 1,15 * 1", at("2026-01-05T00:00:00Z")).toISOString()).toBe("2026-01-12T00:00:00.000Z");
+  expect(nextRun("0 0 1,15 * 1", at("2026-02-09T00:00:00Z")).toISOString()).toBe("2026-02-15T00:00:00.000Z");
+});
+
+test("an unrestricted day field defers to the other one", () => {
+  expect(nextRun("0 0 1-31 * 1", at("2026-01-01T00:00:00Z")).toISOString()).toBe("2026-01-05T00:00:00.000Z");
+  expect(nextRun("0 0 * * 0-6", at("2026-01-01T00:00:00Z")).toISOString()).toBe("2026-01-02T00:00:00.000Z");
+});
+
+test("the 29th of February", () => {
+  expect(nextRun("0 0 29 2 *", at("2096-03-01T00:00:00Z")).toISOString()).toBe("2104-02-29T00:00:00.000Z");
+});
+
+test("an expression that never fires", () => {
+  expect(() => nextRun("0 0 30 2 *", at("2026-01-01T00:00:00Z"))).toThrow(RangeError);
+});
+
+test("an invalid expression", () => {
+  const mid = at("2026-01-01T00:00:00Z");
+  for (const expr of [
+    "*/0 * * * *",
+    "5-1 * * * *",
+    "60 * * * *",
+    "0 24 * * *",
+    "0 0 0 * *",
+    "0 0 32 * *",
+    "0 0 * 13 *",
+    "0 0 * * 8",
+    "0 0 * * FOO",
+    "0 0 * FOO *",
+    "1/2/3 * * * *",
+    ",1 * * * *",
+  ]) {
+    expect(() => nextRun(expr, mid)).toThrow(RangeError);
+  }
+});
