@@ -0,0 +1,53 @@
+import { expect, test } from "bun:test";
+import { nextRun } from "./cron";
+
+const at = (iso: string) => new Date(iso);
+
+test("names are case insensitive", () => {
+  expect(nextRun("0 9 * * MON-FRI", at("2026-01-02T10:00:00Z")).toISOString()).toBe("2026-01-05T09:00:00.000Z");
+  expect(nextRun("0 0 1 Jul *", at("2026-01-01T00:00:00Z")).toISOString()).toBe("2026-07-01T00:00:00.000Z");
+  expect(nextRun("0 0 1 jul *", at("2026-01-01T00:00:00Z")).toISOString()).toBe("2026-07-01T00:00:00.000Z");
+});
+
+test("steps", () => {
+  expect(nextRun("*/15 * * * *", at("2026-01-01T00:07:00Z")).toISOString()).toBe("2026-01-01T00:15:00.000Z");
+  expect(nextRun("10-30/10 * * * *", at("2026-01-01T00:11:00Z")).toISOString()).toBe("2026-01-01T00:20:00.000Z");
+  expect(nextRun("5/20 * * * *", at("2026-01-01T00:05:00Z")).toISOString()).toBe("2026-01-01T00:25:00.000Z");
+  expect(nextRun("5/20 * * * *", at("2026-01-01T00:25:00Z")).toISOString()).toBe("2026-01-01T00:45:00.000Z");
+  expect(nextRun("5/20 * * * *", at("2026-01-01T00:45:00Z")).toISOString()).toBe("2026-01-01T01:05:00.000Z");
+});
+
+test("Sunday as 7", () => {
+  expect(nextRun("0 12 * * 7", at("2026-01-01T00:00:00Z")).toISOString()).toBe("2026-01-04T12:00:00.000Z");
+  expect(nextRun("0 12 * * 0", at("2026-01-01T00:00:00Z")).toISOString()).toBe("2026-01-04T12:00:00.000Z");
+  expect(nextRun("0 12 * * 5-7", at("2026-01-03T13:00:00Z")).toISOString()).toBe("2026-01-04T12:00:00.000Z");
+});
+
+test("a day of month and a day of week together", () => {
+  expect(nextRun("0 0 1,15 * 1", at("2026-01-02T00:00:00Z")).toISOString()).toBe("2026-01-05T00:00:00.000Z");
+  // 1-31 is every day of month, so only the day of week restricts the day.
+  expect(nextRun("0 0 1-31 * 1", at("2026-01-01T00:00:00Z")).toISOString()).toBe("2026-01-05T00:00:00.000Z");
+  // 0-6 is every day of week, so only the day of month restricts the day.
+  expect(nextRun("0 0 1 1 0-6", at("2026-01-02T00:00:00Z")).toISOString()).toBe("2027-01-01T00:00:00.000Z");
+});
+
+test("the 29th of February", () => {
+  expect(nextRun("0 0 29 2 *", at("2026-03-01T00:00:00Z")).toISOString()).toBe("2028-02-29T00:00:00.000Z");
+});
